for path, q, sec, text, fq, fa, claim, src, lab in M:
    p = os.path.join(ROOT, path); t = open(p, encoding='utf-8').read()
    tag = f'<!-- merged: {q} -->'
    if tag in t: continue
    if sec:
        t = t.replace('## Частые вопросы', f'{sec}\n\n{text}\n\n## Частые вопросы', 1)
    if fq:
        t = t.replace('\n## Конспект', f'\n**{fq}**\n{fa}\n\n## Конспект', 1)
    if claim:
        n = len(re.findall(r'^\| \d+ \|', t, re.M)) + 1
        t = t.rstrip('\n') + f'\n| {n} | {claim} | {src} | {lab} | |\n'
    t = t.rstrip('\n') + f'\n{tag}\n'
    open(p, 'w', encoding='utf-8').write(t)
print('склеек:', len(M))
